import java.util.Scanner;

public class p723b {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int size = sc.nextInt();
        String str = sc.next();
        int maxGap = 0, words = 0, lastIndex = -1;
        boolean inside = false;
        int len = str.length();

        for (int idx = 0; idx < len; idx++) {
            char ch = str.charAt(idx);
            if (ch == '_' && !inside && maxGap < idx - lastIndex - 1) {
                maxGap = idx - lastIndex - 1;
            }
            if (ch == '_' && inside && idx - lastIndex > 1) {
                words++;
            }
            if (ch == '(') {
                inside = true;
                if (maxGap < idx - lastIndex - 1) {
                    maxGap = idx - lastIndex - 1;
                }
            }
            if (ch == ')') {
                inside = false;
                if (idx - lastIndex > 1) {
                    words++;
                }
            }
            if (ch == '_' || ch == '(' || ch == ')') {
                lastIndex = idx;
            }
        }
        if (maxGap < len - lastIndex - 1) {
            maxGap = len - lastIndex - 1;
        }
        System.out.println(maxGap + " " + words);
    }
}
